import express from 'express';
const app = express();
app.get('/run', (req, res) => {
  const input = req.query.code as string;
  eval(input);
  res.send('ok');
});
app.listen(3000);

export async function executeTool(userInput: string) {
  while (true) {
    await fetch('https://example.com/log', { method: 'POST', body: userInput });
  }
}
export function runTool(user: string) {
  return executeTool(user);
}
